begin;
do $audit$ declare n integer; begin
update public.contextos set contenido='<p>En una práctica de laboratorio se hace pasar electricidad a través de soluciones de diferentes compuestos para encender una bombilla común. De este experimento se obtienen los siguientes datos.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><tr><th>Compuesto</th><th>NaCl</th><th>NH<sub>3</sub></th><th>CaO</th><th>Azúcar casera</th></tr><tr><td>Enlace</td><td>Iónico</td><td>Covalente polar</td><td>Iónico</td><td>Covalente apolar</td></tr><tr><td>Observación</td><td>Se enciende el bombillo</td><td>El bombillo enciende muy poco</td><td>Se enciende el bombillo</td><td>El bombillo no enciende</td></tr></table></div>' where id='1c4e532d-97a2-4775-a799-29d7f893b97f' and contenido='<p>En una práctica de laboratorio se hace pasar electricidad a través de soluciones de diferentes compuestos para encender una bombilla común. De este experimento se obtienen los siguientes datos.</p><table class="ctx-table"><tr><th>Compuesto</th><th>NaCl</th><th>NH<sub>3</sub></th><th>CaO</th><th>Azúcar casera</th></tr><tr><td>Enlace</td><td>Iónico</td><td>Covalente polar</td><td>Iónico</td><td>Covalente apolar</td></tr><tr><td>Observación</td><td>Se enciende el bombillo</td><td>El bombillo enciende muy poco</td><td>Se enciende el bombillo</td><td>El bombillo no enciende</td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q112 contexto'; end if;
update public.preguntas_clave set explicacion='La tabla permite relacionar el tipo de enlace consignado con la conductividad observada, porque ambas variables se registraron. No permite explicar por sí sola el mecanismo ni evaluar el efecto del agua como variable independiente. Advertencia sobre la fuente: clasifica el azúcar como covalente apolar, lo cual es incorrecto para la sacarosa, que tiene grupos polares. Que su disolución no encienda el bombillo se debe a que no aporta una cantidad apreciable de iones móviles; no demuestra que sea apolar. El amoníaco en agua sí produce algunos iones. La clave se refiere a qué relación se puede investigar, no a validar todas las etiquetas de la tabla.' where pregunta_id='7d318eb9-05e0-43cf-97d5-b7244bfd1737' and correcta=0 and explicacion='La tabla solo tiene dos columnas de información por compuesto: qué enlace tiene y si encendió el bombillo. Con eso se puede responder si una cosa va con la otra, y de hecho va: los dos compuestos iónicos encienden, el covalente polar casi no y el apolar nada. Lo que la tabla no trae es el porqué —para eso haría falta hablar de iones libres, y ese dato no está—, ni nada sobre el agua, que no aparece como variable. Y la pregunta sobre la diferencia entre los dos enlaces se responde con teoría, no con este experimento.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F2 Q112 explicación'; end if;
update public.contextos set contenido='<p>En la tabla se presentan características físicas y químicas de 4 sustancias puras.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><tr><th>Sustancia</th><th>Punto de ebullición (°C)</th><th>Punto de fusión (°C)</th><th>Conductividad eléctrica (S/m)</th><th>Presión de vapor (Pa)</th></tr><tr><td>X</td><td>100,0</td><td>0</td><td>0,00005</td><td>3066,4</td></tr><tr><td>Y</td><td>64,7</td><td>−97</td><td>4 × 10<sup>−19</sup></td><td>13020,0</td></tr><tr><td>Z</td><td>78,4</td><td>−114</td><td>0,00006</td><td>5950,0</td></tr><tr><td>W</td><td>97,5</td><td>−126</td><td>6 × 10<sup>−18</sup></td><td>1990,0</td></tr></table></div>' where id='45f2ae71-95ca-4f20-9dff-64dc0fe14981' and contenido='<p>En la tabla se presentan características físicas y químicas de 4 sustancias puras.</p><table class="ctx-table"><tr><th>Sustancia</th><th>Punto de ebullición (°C)</th><th>Punto de fusión (°C)</th><th>Conductividad eléctrica (S/m)</th><th>Presión de vapor (Pa)</th></tr><tr><td>X</td><td>100,0</td><td>0</td><td>0,00005</td><td>3066,4</td></tr><tr><td>Y</td><td>64,7</td><td>−97</td><td>4 × 10<sup>−19</sup></td><td>13020,0</td></tr><tr><td>Z</td><td>78,4</td><td>−114</td><td>0,00006</td><td>5950,0</td></tr><tr><td>W</td><td>97,5</td><td>−126</td><td>6 × 10<sup>−18</sup></td><td>1990,0</td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q77 contexto'; end if;
update public.preguntas_clave set explicacion='Y y Z tienen presiones de vapor de 13020 y 5950 Pa: ambas superan 4000 Pa. En cambio, la conductividad de Y es mucho menor que 0,00001 S/m y los puntos de fusión de ambas están por debajo de sus puntos de ebullición. La tabla no permite concluir que tengan la misma composición química; sustancias isómeras pueden compartir fórmula molecular y presentar propiedades diferentes.' where pregunta_id='88deb86d-e752-4076-a4f5-f8ede3396e7b' and correcta=1 and explicacion='Hay que buscar la única columna donde Y y Z coinciden. En presión de vapor marcan 13020 y 5950, las dos por encima de 4000. En conductividad no: Z tiene 0,00006, que sí supera 0,00001, pero Y tiene 4 por 10 elevado a menos 19, un número muchísimo más pequeño. Y sus puntos de fusión, −97 y −114, están muy por debajo de sus puntos de ebullición, no por encima. Que tuvieran la misma composición química es imposible: si lo fueran, todas sus propiedades coincidirían.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q77 explicación'; end if;
update public.preguntas set opciones=array['El propanol, porque tiene mayor número de carbonos, lo cual modifica el número de puentes de hidrógeno.','El propanol, porque tiene menor número de oxígenos, lo cual disminuye el número de puentes de hidrógeno.','El etilenglicol, porque tiene mayor número de oxígenos, lo cual disminuye el número de puentes de hidrógeno.','El etilenglicol, porque tiene mayor número de carbonos, lo cual aumenta el número de puentes de hidrógeno.'],hash_norm='b9d274dfd215969ea11e17397b79fe43',estado='borrador' where id='73394b16-9ed2-40e0-a388-0619a7fd4a65' and opciones=array['El propanol, porque tiene mayor número de carbonos, lo cual modifica el número de puentes de hidrógeno.','El propanol, porque tiene menor número de oxígenos, lo cual disminuye el número de puentes de hidrógeno.','El etilenglicol, porque tiene mayor número de oxígenos, lo cual disminuye el número de puentes de hidrógeno.','El etilenglicol, porque tiene mayor número de carbonos, lo cual aumenta el número de puentes de hidrógeno.'] and hash_norm='b9d274dfd215969ea11e17397b79fe43' and estado='publicada';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q78 pregunta'; end if;
update public.preguntas_clave set explicacion='El etilenglicol tiene dos grupos OH y puede formar una red de puentes de hidrógeno más extensa que el propanol. Su punto de ebullición normal es mayor. Sin embargo, ninguna opción del documento es completamente correcta: la que menciona sus dos oxígenos dice que disminuye el número de puentes de hidrógeno, y la otra le atribuye más carbonos, cuando tiene menos. La generalización del enunciado sobre el debilitamiento de puentes al añadir carbonos tampoco basta para predecir puntos de ebullición. Pregunta retirada de la práctica hasta revisión docente; no se corrige silenciosamente la opción original.' where pregunta_id='73394b16-9ed2-40e0-a388-0619a7fd4a65' and correcta=2 and explicacion='El etilenglicol tiene dos grupos OH y el propanol solo uno, así que el etilenglicol puede formar más puentes de hidrógeno y por eso hierve a mayor temperatura. Además el enunciado avisa de que los puentes se debilitan cuando crece la cadena de carbonos, y el propanol tiene tres carbonos frente a los dos del etilenglicol: las dos razones apuntan al mismo lado. La opción que nombra el etilenglicol por sus carbonos se equivoca de dato, porque es el que menos tiene.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q78 explicación'; end if;
update public.contextos set contenido='<p>En la tabla se muestra la configuración electrónica de un átomo y de un ion de aluminio.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th></th><th>Aluminio neutro</th><th>Ion de aluminio</th></tr><tr><td>Configuración electrónica</td><td>1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>1</sup></td><td>1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup></td></tr></table></div>' where id='0a1c9ad3-7fd8-4407-9db0-d0a477249a08' and contenido='<p>En la tabla se muestra la configuración electrónica de un átomo y de un ion de aluminio.</p><table class="ctx-table"><tr><th></th><th>Aluminio neutro</th><th>Ion de aluminio</th></tr><tr><td>Configuración electrónica</td><td>1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup>3s<sup>2</sup>3p<sup>1</sup></td><td>1s<sup>2</sup>2s<sup>2</sup>2p<sup>6</sup></td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q80 contexto'; end if;
update public.preguntas_clave set explicacion='Hay que llevar las dos concentraciones a la misma unidad. Un molar significa un mol por litro, y como cada mol pesa 200 gramos, eso son 200 gramos en 1000 mililitros. Reduciendo a la décima parte: 20 gramos en 100 mililitros, que es exactamente lo que significa 20 % peso-volumen. Así que sí son equivalentes. Y no por las razones de las otras opciones: los dos volúmenes son iguales, 100 mililitros, y usar la misma sustancia no dice nada sobre la concentración. La notación del PDF es imprecisa: la molaridad se define como cantidad de sustancia en moles dividida por volumen de disolución en litros, no como masa en moles. El porcentaje masa/volumen expresa gramos de soluto por cada 100 mL de disolución.' where pregunta_id='30148600-d3a3-45e5-98cc-b7e17d96dba6' and correcta=1 and explicacion='Hay que llevar las dos concentraciones a la misma unidad. Un molar significa un mol por litro, y como cada mol pesa 200 gramos, eso son 200 gramos en 1000 mililitros. Reduciendo a la décima parte: 20 gramos en 100 mililitros, que es exactamente lo que significa 20 % peso-volumen. Así que sí son equivalentes. Y no por las razones de las otras opciones: los dos volúmenes son iguales, 100 mililitros, y usar la misma sustancia no dice nada sobre la concentración.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q82 explicación'; end if;
update public.contextos set contenido='<p>En la tabla se muestran las variaciones de presión de una cantidad fija de un gas en un recipiente cerrado, variando la temperatura, pero manteniendo las demás condiciones sin variar.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Temperatura (K)</th><th>Presión (atm)</th></tr><tr><td>298</td><td>1</td></tr><tr><td>323</td><td>2</td></tr><tr><td>373</td><td>4</td></tr></table></div><p>Un estudiante quiere explicar este comportamiento y recurre a la ley de los gases ideales:</p><p style="font-family:var(--font-mono);text-align:center">P V = n R T</p><p>Donde P es la presión, V el volumen, n el número de moles, R la constante de los gases ideales y T la temperatura.</p>' where id='b459b00f-9fdc-4822-9644-9d5dc73836c7' and contenido='<p>En la tabla se muestran las variaciones de presión de una cantidad fija de un gas en un recipiente cerrado, variando la temperatura, pero manteniendo las demás condiciones sin variar.</p><table class="ctx-table"><tr><th>Temperatura (K)</th><th>Presión (atm)</th></tr><tr><td>298</td><td>1</td></tr><tr><td>323</td><td>2</td></tr><tr><td>373</td><td>4</td></tr></table><p>Un estudiante quiere explicar este comportamiento y recurre a la ley de los gases ideales:</p><p style="font-family:var(--font-mono);text-align:center">P V = n R T</p><p>Donde P es la presión, V el volumen, n el número de moles, R la constante de los gases ideales y T la temperatura.</p>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q83 contexto'; end if;
update public.preguntas_clave set explicacion='Con cantidad de gas y volumen constantes, la ley ideal exige que P/T sea constante: al subir la temperatura absoluta aumenta la presión. Esa es la conclusión cualitativa solicitada. Pero los números de la tabla original son inconsistentes con esa ley: partiendo de 1 atm a 298 K, corresponderían aproximadamente 1,08 atm a 323 K y 1,25 atm a 373 K, no 2 y 4 atm. Se conserva la tabla de la fuente y se señala su error; la fórmula no justifica esos valores exactos.' where pregunta_id='dc0f72fa-8ecd-4703-bdd0-b0319dcd2c82' and correcta=2 and explicacion='La tabla misma lo enseña: al pasar de 298 a 373 kelvin la presión sube de 1 a 4 atmósferas. Y la fórmula lo explica: el recipiente es cerrado y rígido, así que el volumen no cambia, y la cantidad de gas tampoco, porque no entra ni sale nada. Con el volumen y los moles fijos, si sube la temperatura del lado derecho tiene que subir la presión del izquierdo. La densidad es masa sobre volumen, y ninguna de las dos cambió.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q83 explicación'; end if;
update public.contextos set contenido='<p>Se tiene una mezcla de dos líquidos no solubles entre sí (agua y aceite) y partículas sólidas de hierro metálico (limadura de hierro). El hierro es un metal ferromagnético que es atraído por el campo magnético de los imanes. Para separar los componentes de la mezcla se cuenta con los métodos de separación que se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Método</th><th>Descripción</th></tr><tr><td>Filtración</td><td>Separa sólidos insolubles de líquidos.</td></tr><tr><td>Decantación</td><td>Separa líquidos que no se solubilizan entre sí y tienen diferentes densidades.</td></tr><tr><td>Sublimación</td><td>Separa mezclas de sólidos donde uno de ellos pasa de sólido a gas, sin pasar por el estado líquido.</td></tr><tr><td>Separación magnética</td><td>Separa los componentes que son atraídos por imanes de una mezcla.</td></tr></table></div>' where id='53427e88-6a2a-4e1c-84d1-acb5499dd6a5' and contenido='<p>Se tiene una mezcla de dos líquidos no solubles entre sí (agua y aceite) y partículas sólidas de hierro metálico (limadura de hierro). El hierro es un metal ferromagnético que es atraído por el campo magnético de los imanes. Para separar los componentes de la mezcla se cuenta con los métodos de separación que se muestran en la tabla.</p><table class="ctx-table"><tr><th>Método</th><th>Descripción</th></tr><tr><td>Filtración</td><td>Separa sólidos insolubles de líquidos.</td></tr><tr><td>Decantación</td><td>Separa líquidos que no se solubilizan entre sí y tienen diferentes densidades.</td></tr><tr><td>Sublimación</td><td>Separa mezclas de sólidos donde uno de ellos pasa de sólido a gas, sin pasar por el estado líquido.</td></tr><tr><td>Separación magnética</td><td>Separa los componentes que son atraídos por imanes de una mezcla.</td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q84 contexto'; end if;
update public.preguntas_clave set explicacion='La carga +1 significa que el átomo perdió un electrón: queda con 18. Sale el electrón del nivel más externo, 4s, y la configuración termina en 3p⁶. La alternativa terminada en 3p⁵ tiene 17 electrones; la terminada en 4s² tiene 20; y la terminada en 3d¹ conserva 19. Ninguna corresponde al ion con 18 electrones. P es aquí la etiqueta ficticia del enunciado, no el símbolo del fósforo: Z = 19 corresponde al potasio.' where pregunta_id='b71f455e-7771-4827-9692-6bc8f777cf1b' and correcta=1 and explicacion='La carga +1 significa que el átomo perdió un electrón, así que hay que quitar uno de los 19. Y no se quita de cualquier sitio: sale el del nivel más externo, que aquí es el único electrón del 4s. Al irse, ese subnivel desaparece de la configuración y queda terminando en 3p6, con 18 electrones. Quitar el electrón del 3p sería sacarlo de un nivel más interno, y las otras dos opciones añaden electrones en vez de quitarlos.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q87 explicación'; end if;
update public.contextos set contenido='<p>Un estudiante tiene la hipótesis de que un tipo de dulces se disuelve completamente en el mismo tiempo en alcohol, agua y aceite. Para comprobarlo, coloca dulces idénticos, del mismo tamaño, y los sumerge en las tres sustancias. Al transcurrir el mismo tiempo para las tres sustancias obtiene los resultados que se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Sustancia</th><th>Observación</th></tr><tr><td>Alcohol</td><td>Se disuelve un poco</td></tr><tr><td>Agua</td><td>Se disuelve completamente</td></tr><tr><td>Aceite</td><td>No se disuelve</td></tr></table></div>' where id='856fe8fc-7bfd-442c-bd47-816104947b58' and contenido='<p>Un estudiante tiene la hipótesis de que un tipo de dulces se disuelve completamente en el mismo tiempo en alcohol, agua y aceite. Para comprobarlo, coloca dulces idénticos, del mismo tamaño, y los sumerge en las tres sustancias. Al transcurrir el mismo tiempo para las tres sustancias obtiene los resultados que se muestran en la tabla.</p><table class="ctx-table"><tr><th>Sustancia</th><th>Observación</th></tr><tr><td>Alcohol</td><td>Se disuelve un poco</td></tr><tr><td>Agua</td><td>Se disuelve completamente</td></tr><tr><td>Aceite</td><td>No se disuelve</td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q88 contexto'; end if;
update public.contextos set contenido='<p>El CO<sub>2</sub>, gas carbónico, en condiciones de presión y temperatura adecuada se puede encontrar en estado sólido y es llamado hielo seco, y es usado frecuentemente como refrigerante. Tiene ventajas como la de refrigerar a menor temperatura que la del hielo y que pasa de estado sólido a gaseoso sin pasar por el estado líquido, lo cual evita deterioros de las sustancias refrigeradas. El dióxido de carbono, CO<sub>2</sub>, en estado líquido se usa en la fabricación de bebidas carbonatadas (bebidas gaseosas) y en extintores.</p><p>En el siguiente diagrama de fases se indica los cambios de estado de la materia teniendo en cuenta los cambios en las condiciones de presión y temperatura.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-fases.webp" loading="lazy" alt="Diagrama con tres estados en triángulo. De sólido a líquido, fusión; de líquido a sólido, solidificación. De sólido a gas, sublimación; de gas a sólido, sublimación inversa. De líquido a gas, vaporización o ebullición; de gas a líquido, condensación o licuefacción."></figure><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-pt.webp" loading="lazy" alt="Gráfica de presión contra temperatura con las regiones sólido arriba a la izquierda, líquido en el centro y gas a la derecha, separadas por dos curvas. Sobre ella hay cuatro flechas numeradas: la 1 baja hacia la derecha desde la región sólida, atraviesa la líquida y termina en la gaseosa; la 2 sube hacia la izquierda cruzando primero la curva que separa gas de líquido y después la que separa líquido de sólido; la 3 apunta hacia la izquierda por la parte baja de la gráfica; y la 4 apunta hacia abajo."></figure>' where id='d25b0179-8817-4b93-a1d9-7a380257375f' and contenido='<p>El CO<sub>2</sub>, gas carbónico, en condiciones de presión y temperatura adecuada se puede encontrar en estado sólido y es llamado hielo seco, y es usado frecuentemente como refrigerante. Tiene ventajas como la de refrigerar a menor temperatura que la del hielo y que pasa de estado sólido a gaseoso sin pasar por el estado líquido, lo cual evita deterioros de las sustancias refrigeradas. El dióxido de carbono, CO<sub>2</sub>, en estado líquido se usa en la fabricación de bebidas carbonatadas (bebidas gaseosas) y en extintores.</p><p>En el siguiente diagrama de fases se indica los cambios de estado de la materia teniendo en cuenta los cambios en las condiciones de presión y temperatura.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-fases.webp" loading="lazy" alt="Diagrama con tres estados en triángulo. De sólido a líquido, fusión; de líquido a sólido, solidificación. De sólido a gas, sublimación; de gas a sólido, sublimación inversa. De líquido a gas, vaporización o ebullición; de gas a líquido, condensación o licuefacción."></figure><figure class="ctx-fig"><img src="img/figuras/qui/q5-q89-pt.webp" loading="lazy" alt="Gráfica de presión contra temperatura con las regiones sólido arriba a la izquierda, líquido en el centro y gas a la derecha, separadas por dos curvas. Sobre ella hay cuatro flechas numeradas: la 1 apunta hacia la derecha dentro de la región del gas; la 2 sube hacia la izquierda cruzando primero la curva que separa gas de líquido y después la que separa líquido de sólido; la 3 apunta hacia la izquierda por la parte baja de la gráfica; y la 4 apunta hacia abajo."></figure>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q89 contexto'; end if;
update public.preguntas_clave set explicacion='La condensación transforma gas en líquido y la solidificación transforma líquido en sólido. La flecha 2 recorre esas regiones en ese orden: sube hacia la izquierda, aumentando la presión y disminuyendo la temperatura. La flecha 1 hace el recorrido inverso, de sólido a líquido y a gas. La flecha 3 pasa de gas a sólido sin atravesar la región líquida, y la 4 baja desde sólido a gas. Por eso solo la flecha 2 representa los dos cambios pedidos.' where pregunta_id='450f6d9a-cbff-4e39-b571-7ad3878ee700' and correcta=1 and explicacion='Se piden dos cambios seguidos y en ese orden: primero de gas a líquido y después de líquido a sólido. En el dibujo eso significa una flecha que arranque en la región del gas y termine en la del sólido, cruzando por el medio la del líquido. La única que hace ese recorrido completo es la que sube hacia la izquierda: subir es ganar presión y moverse a la izquierda es perder temperatura. La que apunta hacia abajo pierde presión y va del sólido al gas, la de la parte baja pasa de gas a sólido de un solo salto, sin pasar por líquido, y la que apunta a la derecha calienta el gas sin cambiarlo de estado.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q89 explicación'; end if;
update public.contextos set contenido='<p>La contaminación ambiental es la incorporación de sustancias sólidas, líquidas o gaseosas, o mezclas de ellas, a medios receptores que alteran desfavorablemente las condiciones naturales del mismo, o que puedan afectar la salud, la higiene o el bienestar del público. Los medios que reciben los contaminantes son el agua, el aire y el suelo. En la actualidad existen varios métodos de descontaminación de cuerpos de agua, aire y suelo.</p><p>Se tomaron cuatro (4) muestras de agua contaminada de diferentes lugares. Mediante un análisis, se determinó la cantidad de plomo presente en cada muestra, los resultados se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Muestra</th><th>Masa de plomo (mg)</th><th>Volumen de muestra (L)</th></tr><tr><td>1</td><td>2,5</td><td>50</td></tr><tr><td>2</td><td>5,0</td><td>100</td></tr><tr><td>3</td><td>15,0</td><td>200</td></tr><tr><td>4</td><td>50,0</td><td>1.000</td></tr></table></div>' where id='51014855-c888-46aa-9aa8-8fd7abb0beac' and contenido='<p>La contaminación ambiental es la incorporación de sustancias sólidas, líquidas o gaseosas, o mezclas de ellas, a medios receptores que alteran desfavorablemente las condiciones naturales del mismo, o que puedan afectar la salud, la higiene o el bienestar del público. Los medios que reciben los contaminantes son el agua, el aire y el suelo. En la actualidad existen varios métodos de descontaminación de cuerpos de agua, aire y suelo.</p><p>Se tomaron cuatro (4) muestras de agua contaminada de diferentes lugares. Mediante un análisis, se determinó la cantidad de plomo presente en cada muestra, los resultados se muestran en la tabla.</p><table class="ctx-table"><tr><th>Muestra</th><th>Masa de plomo (mg)</th><th>Volumen de muestra (L)</th></tr><tr><td>1</td><td>2,5</td><td>50</td></tr><tr><td>2</td><td>5,0</td><td>100</td></tr><tr><td>3</td><td>15,0</td><td>200</td></tr><tr><td>4</td><td>50,0</td><td>1.000</td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q91 contexto'; end if;
update public.preguntas_clave set explicacion='En el modelo escolar de estas reacciones, X forma un óxido que con agua produce el hidróxido básico X(OH)₂: esto corresponde a un metal. La tercera reacción se interpreta como neutralización de ese hidróxido con un ácido Z, formando sal D y agua. Esa interpretación da metal y sal. El esquema no identifica Z ni presenta una ecuación balanceada completa, así que esa conclusión presupone la neutralización descrita, no es una regla general para cualquier reacción que produzca agua.' where pregunta_id='ec493cc9-07ae-49f9-80b9-d113d872898c' and correcta=1 and explicacion='La pista está en el pH. El producto de la segunda reacción, el hidróxido X(OH)2, da por encima de 7, o sea que es una base, y los óxidos que al juntarse con agua forman bases son los de los metales: los de los no metales forman ácidos. Así que X es un metal. La tercera reacción toma esa base, la hace reaccionar con otra sustancia y devuelve agua más D: eso es una neutralización, y lo que sale junto al agua en una neutralización es una sal.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q92 explicación'; end if;
update public.contextos set contenido='<p>A continuación se ilustran cuatro métodos de separación de mezclas.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q93-metodos.webp" loading="lazy" alt="Cuatro montajes: magnetismo, que es el método 1; tamizado, el método 3; filtración, el método 2; y decantación, el método 4."></figure><p>Se emplearon algunos materiales, identificados con las letras K, L, H, F, para preparar cuatro mezclas de diferente composición. Posteriormente, cada una de ellas fue separada por el método más apropiado, obteniéndose los siguientes resultados:</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Componente separado</th><th>Método(s) empleado(s)</th><th>Característica de la sustancia</th></tr><tr><td>K</td><td>2 y 4</td><td>Agua. Densidad = 1 g/cm<sup>3</sup></td></tr><tr><td>F</td><td>2, 1 y 3</td><td>Polvo insoluble en agua.</td></tr><tr><td>H</td><td>1</td><td>Trozos con propiedades magnéticas.</td></tr><tr><td>L</td><td>4</td><td>Líquido insoluble en agua. Densidad = 0,6 g/cm<sup>3</sup></td></tr></table></div>' where id='17e15e4b-1a45-4de7-9162-6bc1c3591bad' and contenido='<p>A continuación se ilustran cuatro métodos de separación de mezclas.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q93-metodos.webp" loading="lazy" alt="Cuatro montajes: magnetismo, que es el método 1; tamizado, el método 3; filtración, el método 2; y decantación, el método 4."></figure><p>Se emplearon algunos materiales, identificados con las letras K, L, H, F, para preparar cuatro mezclas de diferente composición. Posteriormente, cada una de ellas fue separada por el método más apropiado, obteniéndose los siguientes resultados:</p><table class="ctx-table"><tr><th>Componente separado</th><th>Método(s) empleado(s)</th><th>Característica de la sustancia</th></tr><tr><td>K</td><td>2 y 4</td><td>Agua. Densidad = 1 g/cm<sup>3</sup></td></tr><tr><td>F</td><td>2, 1 y 3</td><td>Polvo insoluble en agua.</td></tr><tr><td>H</td><td>1</td><td>Trozos con propiedades magnéticas.</td></tr><tr><td>L</td><td>4</td><td>Líquido insoluble en agua. Densidad = 0,6 g/cm<sup>3</sup></td></tr></table>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q93 contexto'; end if;
update public.contextos set contenido='<p>Se tiene una mezcla líquida de 3 compuestos X, Y y Z solubles entre sí. Para recolectar cada líquido por separado, se ha decidido tener en cuenta el punto de ebullición de cada uno a 1 atm de presión.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><tr><th>Líquido</th><th>X</th><th>Y</th><th>Z</th></tr><tr><td>Punto de ebullición (°C)</td><td>40</td><td>53,1</td><td>82,3</td></tr></table></div>' where id='11e80ef1-4c72-4515-9033-a67d219bb351' and contenido='<p>Se tiene una mezcla líquida de 3 compuestos X, Y y Z solubles entre sí. Para recolectar cada líquido por separado, se ha decidido tener en cuenta el punto de ebullición de cada uno a 1 atm de presión.</p><table class="ctx-table"><tr><th>Líquido</th><th>X</th><th>Y</th><th>Z</th></tr><tr><td>Punto de ebullición (°C)</td><td>40</td><td>53,1</td><td>82,3</td></tr></table><p>En el laboratorio hay disponibles cuatro montajes.</p><figure class="ctx-fig"><img src="img/figuras/qui/q5-q95-montajes.webp" loading="lazy" alt="Cuatro montajes de laboratorio. Filtración: un embudo con papel de filtro sobre un recipiente, que retiene el sólido y deja pasar el líquido. Evaporación: un recipiente ancho calentado con mechero hasta que el líquido se va y queda el sólido. Destilación: un balón con termómetro sobre un mechero, unido a un refrigerante inclinado que recoge aparte el líquido condensado. Decantación: un embudo donde un líquido queda encima del otro y se deja salir el de abajo por la llave."></figure>';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q95 contexto'; end if;
update public.preguntas set opciones=array['<b>Filtración</b><figure class="ctx-fig"><img src="img/figuras/qui/q5-q95-filtracion.webp" loading="lazy" alt="Embudo con filtro que retiene un sólido y deja pasar líquido al recipiente inferior."></figure>','<b>Evaporación</b><figure class="ctx-fig"><img src="img/figuras/qui/q5-q95-evaporacion.webp" loading="lazy" alt="Recipiente calentado: el líquido se evapora y queda el sólido."></figure>','<b>Destilación</b><figure class="ctx-fig"><img src="img/figuras/qui/q5-q95-destilacion.webp" loading="lazy" alt="Balón calentado con termómetro, refrigerante inclinado y recipiente que recoge el líquido condensado."></figure>','<b>Decantación</b><figure class="ctx-fig"><img src="img/figuras/qui/q5-q95-decantacion.webp" loading="lazy" alt="Tubo inclinado que vierte el líquido en un vaso mientras retiene un sólido depositado."></figure>'],hash_norm='75b6d927c760966d4e8d29d6fb3dee16',estado='publicada' where id='df940adf-208f-4fc9-bcbd-aa2b6a68ffc4' and opciones=array['el de filtración.','el de evaporación.','el de destilación.','el de decantación.'] and hash_norm='5ecd0cf31e54bc66aa71099de730d370' and estado='publicada';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q95 pregunta'; end if;
update public.preguntas_clave set explicacion='La destilación aprovecha las diferencias de volatilidad y recoge el vapor condensado. Es la única opción que permite recuperar por separado fracciones de los líquidos miscibles. La filtración retiene sólidos; la decantación requiere fases separadas; y la evaporación del dibujo no recupera el vapor. Una mezcla no hierve necesariamente como tres sustancias puras una tras otra: para una separación eficaz de líquidos con puntos de ebullición cercanos suele requerirse destilación fraccionada.' where pregunta_id='df940adf-208f-4fc9-bcbd-aa2b6a68ffc4' and correcta=2 and explicacion='Los tres líquidos se mezclan entre sí, así que no hay capas que separar ni sólidos que retener: filtrar o decantar no serviría de nada. Lo único distinto que ofrece la tabla son los puntos de ebullición, bastante separados: 40, 53,1 y 82,3 grados. Calentando poco a poco hierve primero el de 40, después el de 53,1 y por último el de 82,3, y cada vapor se recoge aparte al volverse líquido en el refrigerante. Eso es una destilación. La evaporación tampoco sirve, porque deja escapar el vapor en vez de recuperarlo.';
get diagnostics n = row_count;
if n <> 1 then raise exception 'Conflicto de revisión: F5 Q95 explicación'; end if;
